def pode(usuario, recurso, acao):
    if usuario is None:
        return False, 401                 # não sei quem é você

    if usuario.get("perfil") == "admin":
        return True, 200                  # admin passa por cima da checagem de dono

    if recurso is None:
        return False, 404

    if recurso.get("usuario_id") != usuario["id"]:
        return False, 403                 # sei quem é você, e não é seu

    if acao == "apagar" and recurso.get("bloqueada"):
        return False, 409                 # conflito com o estado atual

    return True, 200

