class Repositorio:
    ALTERAVEIS = ("titulo", "feita")      # o que o cliente pode mudar, e só isso

    def __init__(self):
        self._itens = {}
        self._proximo = 1

    def listar(self, dono):
        return [i for i in self._itens.values() if i["usuario_id"] == dono]

    def criar(self, dono, titulo):
        item = {"id": self._proximo, "usuario_id": dono, "titulo": titulo.strip(), "feita": False}
        self._itens[self._proximo] = item
        self._proximo += 1
        return item

    def _meu(self, dono, id):
        item = self._itens.get(id)
        return item if item and item["usuario_id"] == dono else None

    def alterar(self, dono, id, campos):
        item = self._meu(dono, id)
        if item is None:
            return None
        for campo in self.ALTERAVEIS:
            if campo in campos:
                item[campo] = campos[campo]
        return item

    def apagar(self, dono, id):
        if self._meu(dono, id) is None:
            return False
        del self._itens[id]
        return True

